/**
 * @summary Download the signed PDF for a specific signing attempt of an uploaded file.
Storage key is resolved server-side — client never passes bucket/key.
Prefer requestId (the SigningRequest PublicId) so each independent sign of the
same file is retrievable; sequence is the legacy fallback (latest at that step).
Cross-tenant / cross-file id → 404. Attempt not yet Completed → 404.
Tenant always resolved from JWT — never from query param (IDOR prevention).
 */

export function useGetApiV1FilesIdSigned<TData = Awaited<ReturnType<typeof getApiV1FilesIdSigned>>, TError = ProblemDetails>(
 id: string,
    params?: GetApiV1FilesIdSignedParams, options?: { query?:Partial<UseQueryOptions<Awaited<ReturnType<typeof getApiV1FilesIdSigned>>, TError, TData>>, }
 , queryClient?: QueryClient
 ):  UseQueryResult<TData, TError> & { queryKey: DataTag<QueryKey, TData, TError> } {

  const queryOptions = getGetApiV1FilesIdSignedQueryOptions(id,params,options)

  const query = useQuery(queryOptions, queryClient) as  UseQueryResult<TData, TError> & { queryKey: DataTag<QueryKey, TData, TError> };

  return withQueryKey(query, queryOptions.queryKey);
}






